#!/bin/sh
# Production start, the image's CMD (generated by Shikshya): apply the committed migrations, then serve. It never
# installs packages and never makes migrations; previews run start.sh instead. It seeds only when SEED_DEMO=1, which
# Shikshya Cloud sets for an app's first deploy alone (then 0): the demo data and this app's demo sign-ins, loaded as
# start.sh loads them. Never set SEED_DEMO on a database with real users.
set -eu
cd "$(dirname "$0")/.."
python manage.py migrate --noinput
if [ "${SEED_DEMO:-0}" = "1" ] && [ -f seed_data.json ]; then
    python manage.py shell -c "
from django.contrib.auth import get_user_model
U = get_user_model()
U.objects.filter(username='demo').exists() or U.objects.create_user('demo', 'demo@example.com')
" || echo "WARNING: the demo user was not created"
    python manage.py loaddata seed_data.json || echo "WARNING: the seed data did not load"
fi
if [ "${SEED_DEMO:-0}" = "1" ] && [ -f seed_accounts.py ]; then
    python manage.py shell < seed_accounts.py || echo "WARNING: demo sign-ins were not set up"
fi
exec daphne --proxy-headers -b 0.0.0.0 -p "${PORT:-8000}" config.asgi:application
